/// The gallery's example of `Splitter`, with its settings taken from the story.
#[allow(unused_variables, unused_mut, clippy::redundant_clone, clippy::let_and_return, clippy::clone_on_copy)]
fn render(args: &Args) -> AnyView {
    Box::new({
        let arg_ratio = args.number("ratio") as f32;
        let arg_height = args.number("height") as f32;

        {
            let mut it =
                Splitter::horizontal(Text::new("Explorer").padding(16.0), Text::new("Editor").padding(16.0));
            it = it.ratio(arg_ratio);
            it = it.height(arg_height);
            it
        }
    })
}

impl ComponentBook for Splitter<AnyView, AnyView> {
    fn book() -> Meta {
        Meta::new("Layout/Splitter", render)
            .summary("Two panes with a draggable divider.")
            .arg(ArgType::number("ratio", 0.32, 0.0, 1.28, 0.01))
            .arg(ArgType::number("height", 190.0, 0.0, 760.0, 1.0))
            .story("Example", Args::new())
    }
}
